def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    a0, a1, a2, a3, a4 = parameters
    return a0 + a1 * np.log(gate_voltage_abs) + a2 * np.log(gate_voltage_abs**2) + a3 * np.log(drain_voltage_abs) + a4 * np.log(drain_voltage_abs**2)
